ALTER TABLE public.coach_interventions ADD COLUMN IF NOT EXISTS claim_key text, ADD COLUMN IF NOT EXISTS claimed_at timestamptz, ADD COLUMN IF NOT EXISTS applied_values jsonb; CREATE OR REPLACE FUNCTION public.claim_intervention(p_id uuid, p_claim_key text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_row public.coach_interventions%ROWTYPE; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF; IF p_id IS NULL OR p_claim_key IS NULL OR length(p_claim_key) < 8 THEN RAISE EXCEPTION 'Invalid claim'; END IF; SELECT * INTO v_row FROM public.coach_interventions WHERE id = p_id FOR UPDATE; IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'reason', 'not_found'); END IF; IF v_row.coach_id <> auth.uid() THEN RAISE EXCEPTION 'Not this coach'; END IF; IF v_row.status <> 'pending' THEN RETURN jsonb_build_object('ok', false, 'reason', 'already_resolved'); END IF; IF v_row.claim_key IS NOT NULL AND v_row.claim_key <> p_claim_key THEN IF v_row.claimed_at IS NOT NULL AND v_row.claimed_at > now() - interval '15 minutes' THEN RETURN jsonb_build_object('ok', false, 'reason', 'already_claimed'); END IF; END IF; UPDATE public.coach_interventions SET claim_key = p_claim_key, claimed_at = now(), updated_at = now() WHERE id = p_id; RETURN jsonb_build_object('ok', true); END; $$; REVOKE ALL ON FUNCTION public.claim_intervention(uuid, text) FROM PUBLIC, anon; GRANT EXECUTE ON FUNCTION public.claim_intervention(uuid, text) TO authenticated; CREATE OR REPLACE FUNCTION public.release_intervention_claim(p_id uuid, p_claim_key text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF; UPDATE public.coach_interventions SET claim_key = NULL, claimed_at = NULL, updated_at = now() WHERE id = p_id AND coach_id = auth.uid() AND status = 'pending' AND claim_key = p_claim_key; RETURN FOUND; END; $$; REVOKE ALL ON FUNCTION public.release_intervention_claim(uuid, text) FROM PUBLIC, anon; GRANT EXECUTE ON FUNCTION public.release_intervention_claim(uuid, text) TO authenticated; CREATE OR REPLACE FUNCTION public.finalize_intervention(p_id uuid, p_claim_key text, p_status text, p_payload jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_row public.coach_interventions%ROWTYPE; v_applied jsonb := NULL; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF; IF p_status NOT IN ('sent', 'dismissed', 'kept') THEN RAISE EXCEPTION 'Invalid status'; END IF; SELECT * INTO v_row FROM public.coach_interventions WHERE id = p_id FOR UPDATE; IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'reason', 'not_found'); END IF; IF v_row.coach_id <> auth.uid() THEN RAISE EXCEPTION 'Not this coach'; END IF; IF v_row.status <> 'pending' THEN RETURN jsonb_build_object('ok', false, 'reason', 'already_resolved'); END IF; IF v_row.claim_key IS DISTINCT FROM p_claim_key THEN RETURN jsonb_build_object('ok', false, 'reason', 'claim_mismatch'); END IF; IF v_row.kind = 'calorie_adjustment' AND v_row.client_id IS NOT NULL THEN SELECT jsonb_build_object('calories', p.daily_calorie_target, 'protein', p.protein_target, 'carbs', p.carbs_target, 'fat', p.fat_target, 'snapshot_at', now()) INTO v_applied FROM public.user_profiles p WHERE p.id = v_row.client_id; END IF; UPDATE public.coach_interventions SET status = p_status, payload = COALESCE(p_payload, payload), applied_values = COALESCE(v_applied, applied_values), claim_key = NULL, claimed_at = NULL, resolved_at = now(), updated_at = now() WHERE id = p_id; RETURN jsonb_build_object('ok', true, 'applied', v_applied); END; $$; REVOKE ALL ON FUNCTION public.finalize_intervention(uuid, text, text, jsonb) FROM PUBLIC, anon; GRANT EXECUTE ON FUNCTION public.finalize_intervention(uuid, text, text, jsonb) TO authenticated;
